.accordion-body li {
  margin-bottom: 0.5rem;
}

.accordion-body code {
  background: var(--bg-tertiary);
  padding: 0.125rem 0.375rem;
  border-radius: 4px;
  font-family: var(--font-mono);
  font-size: 0.8125rem;
