  margin: 2rem 0;
}

.docs-content .cta-block h3 {
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
}

.docs-content .cta-block p {
  color: var(--text-secondary);
  margin-bottom: 1rem;
}

/* Grid Cards for Docs pages */
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.25rem;
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}

.mini-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 1.25rem;
  transition: all 0.2s;
}

.mini-card:hover {
  border-color: var(--accent-cyan);
  transform: translateY(-2px);
}

.mini-card h4 {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 0.375rem;
}

.mini-card p {
  color: var(--text-secondary);
  font-size: 0.8125rem;
  line-height: 1.5;
}

/* Protocol Actors */
.protocol-actors {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
  margin: 2rem 0;
}

.actor-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 1.5rem;
  text-align: center;
  transition: all 0.3s;
}

.actor-card:hover {
  border-color: var(--accent-cyan);
  transform: scale(1.02);
}

.actor-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1rem;
  font-size: 1.25rem;
  font-weight: 700;
}

.actor-icon.agent { background: rgba(88, 166, 255, 0.15); color: var(--accent-cyan); }
.actor-icon.merchant { background: rgba(163, 113, 247, 0.15); color: var(--accent-purple); }
.actor-icon.cp { background: rgba(210, 153, 34, 0.15); color: var(--accent-orange); }
.actor-icon.psp { background: rgba(63, 185, 80, 0.15); color: var(--accent-green); }

.actor-card h4 {
  font-size: 1rem;
  margin-bottom: 0.375rem;
}

.actor-card p {
  color: var(--text-secondary);
  font-size: 0.8125rem;
}

/* Support Cards */
.support-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 1.5rem;
}

.support-card h3 {
  font-size: 1.0625rem;
  margin-bottom: 0.75rem;
  display: flex;
  align-items: center;
  gap: 0.625rem;
}

.support-card ul {
  list-style: none;
  margin-top: 1rem;
}

.support-card li {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  margin-bottom: 0.5rem;
  padding-left: 1.25rem;
  position: relative;
}

.support-card li::before {
  content: "→";
  position: absolute;
  left: 0;
  color: var(--accent-cyan);
}

/* Responsive */
@media (max-width: 1024px) {
  .docs-sidebar {
    position: fixed;
    left: 0;
    top: 64px;
    z-index: 100;
    transform: translateX(-100%);
  }

  .docs-sidebar.open {
    transform: translateX(0);
  }

  .docs-content {
    padding: 2rem;
  }

  .grid-3, .grid-4 {
    grid-template-columns: repeat(2, 1fr);
  }

  .protocol-actors {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .top-nav {
    padding: 0 1rem;
