  transition: max-height 0.3s ease-out;
}

.accordion.open .accordion-content {
  max-height: 300px;
}

.accordion-body {
  padding: 0 1.25rem 1.25rem;
}

.accordion-body ol {
  margin-left: 1.25rem;
  color: var(--text-secondary);
}

.accordion-body li {
  margin-bottom: 0.5rem;
}

.accordion-body code {
  background: var(--bg-tertiary);
  padding: 0.125rem 0.375rem;
  border-radius: 4px;
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  color: var(--accent-cyan);
}

/* Launch CTA */
.launch-cta {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
  margin: 4rem 0;
}

.launch-card {
  background: linear-gradient(135deg, var(--bg-secondary) 0%, var(--bg-tertiary) 100%);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 2rem;
}

.launch-card h3 {
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
}

.launch-card p {
  color: var(--text-secondary);
  margin-bottom: 1.25rem;
  font-size: 0.9375rem;
}

/* Community Section */
.community-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1rem;
}

.community-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 1.5rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  transition: all 0.2s;
}

.community-card:hover {
  border-color: var(--accent-cyan);
  transform: translateX(4px);
}

.community-icon {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  background: var(--bg-tertiary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-cyan);
}

.community-card span {
  font-weight: 500;
}

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 4rem 2rem 2rem;
  margin-top: 4rem;
}

.footer-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
}

.footer-col h4 {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 1rem;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 0.625rem;
}

.footer-col a {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

.footer-col a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  max-width: 1200px;
  margin: 3rem auto 0;
  padding-top: 2rem;
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-bottom p {
  color: var(--text-muted);
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: 1.5rem;
}

.footer-legal a {
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* Docs Layout (Apps & Agents pages) */
.docs-layout {
  display: flex;
  min-height: calc(100vh - 64px);
}

.docs-sidebar {
  width: 280px;
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  padding: 2rem 1.5rem;
  position: sticky;
  top: 64px;
  height: calc(100vh - 64px);
  overflow-y: auto;
  transition: width 0.3s, padding 0.3s;
}

.docs-sidebar.collapsed {
  width: 0;
  padding: 0;
  overflow: hidden;
}

.sidebar-toggle {
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 0.5rem 0.75rem;
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.8125rem;
  margin-bottom: 1.5rem;
  transition: all 0.2s;
}

.sidebar-toggle:hover {
  border-color: var(--accent-cyan);
  color: var(--text-primary);
}

.sidebar-section {
  margin-bottom: 1.5rem;
}

.sidebar-section-title {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.75rem;
}

.sidebar-links {
  list-style: none;
}

.sidebar-links li {
  margin-bottom: 0.375rem;
}

.sidebar-links a {
  color: var(--text-secondary);
  font-size: 0.875rem;
  padding: 0.5rem 0.75rem;
  border-radius: 6px;
  display: block;
  transition: all 0.2s;
}

.sidebar-links a:hover, .sidebar-links a.active {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.docs-content {
  flex: 1;
  padding: 3rem;
  max-width: 900px;
}

.docs-content h1 {
  font-size: 2.5rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.docs-content .subtitle {
  font-size: 1.125rem;
  color: var(--text-secondary);
  margin-bottom: 2rem;
  line-height: 1.7;
}

.docs-content .cta-block {
  background: linear-gradient(135deg, var(--bg-secondary) 0%, var(--bg-tertiary) 100%);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 2rem;
  margin: 2rem 0;
}

.docs-content .cta-block h3 {
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
}

.docs-content .cta-block p {
  color: var(--text-secondary);
  margin-bottom: 1rem;
}

/* Grid Cards for Docs pages */
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.25rem;
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}

.mini-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 1.25rem;
  transition: all 0.2s;
}

.mini-card:hover {
  border-color: var(--accent-cyan);
  transform: translateY(-2px);
}

.mini-card h4 {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 0.375rem;
}

.mini-card p {
  color: var(--text-secondary);
  font-size: 0.8125rem;
  line-height: 1.5;
}

/* Protocol Actors */
.protocol-actors {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
  margin: 2rem 0;
}

.actor-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 1.5rem;
  text-align: center;
  transition: all 0.3s;
}

.actor-card:hover {
  border-color: var(--accent-cyan);
  transform: scale(1.02);
}

.actor-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1rem;
  font-size: 1.25rem;
  font-weight: 700;
}

.actor-icon.agent { background: rgba(88, 166, 255, 0.15); color: var(--accent-cyan); }
.actor-icon.merchant { background: rgba(163, 113, 247, 0.15); color: var(--accent-purple); }
.actor-icon.cp { background: rgba(210, 153, 34, 0.15); color: var(--accent-orange); }
.actor-icon.psp { background: rgba(63, 185, 80, 0.15); color: var(--accent-green); }

.actor-card h4 {
  font-size: 1rem;
  margin-bottom: 0.375rem;
}

.actor-card p {
  color: var(--text-secondary);
  font-size: 0.8125rem;
}

/* Support Cards */
.support-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 1.5rem;
}

.support-card h3 {
  font-size: 1.0625rem;
  margin-bottom: 0.75rem;
  display: flex;
  align-items: center;
  gap: 0.625rem;
}

.support-card ul {
  list-style: none;
  margin-top: 1rem;
}

.support-card li {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  margin-bottom: 0.5rem;
  padding-left: 1.25rem;
  position: relative;
}

.support-card li::before {
  content: "→";
  position: absolute;
  left: 0;
  color: var(--accent-cyan);
}

/* Responsive */
@media (max-width: 1024px) {
  .docs-sidebar {
    position: fixed;
    left: 0;
    top: 64px;
    z-index: 100;
    transform: translateX(-100%);
  }

  .docs-sidebar.open {
    transform: translateX(0);
  }

  .docs-content {
    padding: 2rem;
  }

  .grid-3, .grid-4 {
    grid-template-columns: repeat(2, 1fr);
  }

  .protocol-actors {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .top-nav {
    padding: 0 1rem;
  }

  .nav-links {
    display: none;
  }

  .hero {
    padding: 4rem 1rem;
  }

  .hero h1 {
    font-size: 2.25rem;
  }

  .section {
    padding: 3rem 1rem;
  }

  .grid-3, .grid-2, .grid-4, .protocol-actors {
    grid-template-columns: 1fr;
  }

  .cli-section {
    padding: 1.5rem;
  }

  .docs-content {
    padding: 1.5rem 1rem;
  }

  .docs-content h1 {
    font-size: 2rem;
  }
}

